    // Sort alphabetically
    pages.sort((a, b) => a.name.localeCompare(b.name));

    // Generate NPCs section
    const npcSection = [
        '## NPCs',
        '',
        '| NPC | Combat Level |',
        '|-----|-------------|',
    ];

    for (const page of pages) {
        // Read back the file to get combat level
        const filePath = join(NPC_DIR, page.file);
        const md = readFileSync(filePath, 'utf-8');
