import { readFileSync, readdirSync } from 'fs';
import { join } from 'path';

const ROOT = 'E:/runebench/rs-sdk';
const CONTENT = join(ROOT, 'server/content');
const mapsDir = join(CONTENT, 'maps');

const packContent = readFileSync(join(CONTENT, 'pack', 'npc.pack'), 'utf-8');
const idToName = new Map<number,string>();
for (const line of packContent.split('\n')) {
  const eq = line.indexOf('=');
  if (eq === -1) continue;
  const id = parseInt(line.slice(0,eq));
  const name = line.slice(eq+1).trim();
  if (!isNaN(id) && name) idToName.set(id, name);
}
const wanted = /mossgiant|icegiant|giantspider|hobgoblin|skeleton|zombie|tribesman|guard|dark_wizard|dwarf|scorpion|al_kharid|monk|barbarian|giant$|giant_/i;
const spawns = new Map<string, {x:number,z:number,lvl:number,dist:number}[]>();
const px=3222, pz=3222;
for (const file of readdirSync(mapsDir).filter(f=>f.endsWith('.jm2'))) {
  const m = file.match(/^m(\d+)_(\d+)\.jm2$/); if(!m) continue;
  const mx=parseInt(m[1]), mz=parseInt(m[2]);
  const content = readFileSync(join(mapsDir,file),'utf-8');
  const idx = content.indexOf('==== NPC ===='); if(idx===-1) continue;
  const after = content.slice(idx+13);
  const next = after.indexOf('===='); const block = next===-1?after:after.slice(0,next);
  for (const line of block.split('\n')) {
    const t=line.trim(); const mm=t.match(/^(\d+)\s+(\d+)\s+(\d+):\s*(\d+)$/); if(!mm) continue;
    const lvl=parseInt(mm[1]), lx=parseInt(mm[2]), lz=parseInt(mm[3]), id=parseInt(mm[4]);
    const name=idToName.get(id); if(!name) continue;
    if(!wanted.test(name)) continue;
    const gx=mx*64+lx, gz=mz*64+lz;
    const dist=Math.round(Math.hypot(gx-px,gz-pz));
    if(dist>900) continue;
    if(!spawns.has(name)) spawns.set(name,[]);
    spawns.get(name)!.push({x:gx,z:gz,lvl,dist});
  }
}
for (const [name, list] of [...spawns.entries()].sort((a,b)=>a[1][0].dist-b[1][0].dist)) {
  const near = list.sort((a,b)=>a.dist-b.dist).slice(0,4);
  console.log(name, 'count='+list.length, near.map(s=>`(${s.x},${s.z})L${s.lvl} d${s.dist}`).join(' '));
}

