import { readFileSync, readdirSync, statSync } from 'fs';
import { join } from 'path';

const ROOT = 'E:/runebench/rs-sdk';
const SCRIPTS = join(ROOT, 'server/content/scripts');

function walk(d: string, out: string[]) {
  for (const e of readdirSync(d, { withFileTypes: true })) {
    const p = join(d, e.name);
    if (e.isDirectory()) walk(p, out);
    else if (e.name.endsWith('.npc')) out.push(p);
  }
}
const files: string[] = [];
walk(SCRIPTS, files);

interface N { name:string; vislevel:number; attack:number; defence:number; strength:number; hitpoints:number; huntmode:string; file:string }
const byName = new Map<string, N>();
for (const f of files) {
  const content = readFileSync(f, 'utf-8');
  let cur: any = null;
  const flush = () => { if (cur && cur.name && cur.vislevel>0) byName.set(cur._key + '|' + cur.name, cur); };
  for (const raw of content.split('\n')) {
    const line = raw.trim();
    const sm = line.match(/^\[([^\]]+)\]$/);
    if (sm) { flush(); cur = { _key: sm[1], name:'', vislevel:0, attack:0, defence:0, strength:0, hitpoints:0, huntmode:'', file:f }; continue; }
    if (!cur) continue;
    const eq = line.indexOf('='); if (eq===-1) continue;
    const k = line.slice(0,eq).trim(), v = line.slice(eq+1).trim();
    if (k==='name') cur.name=v;
    else if (k==='vislevel') cur.vislevel=parseInt(v)||0;
    else if (k==='attack') cur.attack=parseInt(v)||0;
    else if (k==='defence') cur.defence=parseInt(v)||0;
    else if (k==='strength') cur.strength=parseInt(v)||0;
    else if (k==='hitpoints') cur.hitpoints=parseInt(v)||0;
    else if (k==='huntmode') cur.huntmode=v;
  }
  flush();
}
const list = [...byName.values()].filter(n=>n.vislevel>=30);
// estimated value = L*d/(1+d); hitChance approx using our atk=40, weapon bonus 7 -> A=47
const A = 47;
function hitChance(defLv:number, defBonus:number){
  const a=A, d=defLv+defBonus+8;
  if (a+8 > d) return 1-(d+2)/(2*(a+9));
  return (a+8)/(2*(d+1));
}
for (const n of list) {
  const hc = hitChance(n.defence, 0);
  const maxHit = Math.floor((n.strength*64+320)/640);
  const d = hc * (maxHit/2) / 2.4;
  const val = n.vislevel * d/(1+d);
  n['val']=val; n['d']=d; n['maxHit']=maxHit; n['hc']=hc;
}
list.sort((a,b)=>b['val']-a['val']);
for (const n of list.slice(0,40)) {
  console.log(`${n.vislevel}\t${n.name}\tatk${n.attack} def${n.defence} str${n.strength} hp${n.hitpoints}\t${n.huntmode}\tval~${n['val'].toFixed(1)} d${n['d'].toFixed(2)} mh${n['maxHit']}`);
}

