  const flush = () => { if (cur && cur.name && cur.vislevel > 0) byKey.set(cur.key, cur); };
  for (const raw of content.split('\n')) {
    const line = raw.trim();
    const sm = line.match(/^\[([^\]]+)\]$/);
    if (sm) { flush(); cur = { key: sm[1], name:'', vislevel:0, attack:0, defence:0, strength:0, hitpoints:0, huntmode:'', atkB:0, strB:0, stabD:0, slashD:0, crushD:0 }; continue; }
    if (!cur) continue;
    const eq = line.indexOf('='); if (eq === -1) continue;
    const k = line.slice(0,eq).trim(); const v = line.slice(eq+1).trim();
    if (k==='name') cur.name=v;
    else if (k==='vislevel') cur.vislevel=parseInt(v)||0;
    else if (k==='attack') cur.attack=parseInt(v)||0;
    else if (k==='defence') cur.defence=parseInt(v)||0;
    else if (k==='strength') cur.strength=parseInt(v)||0;
    else if (k==='hitpoints') cur.hitpoints=parseInt(v)||0;
    else if (k==='huntmode') cur.huntmode=v;
    else if (k==='param') { const c=v.indexOf(','); if(c===-1) continue; const pk=v.slice(0,c).trim(); const pv=parseInt(v.slice(c+1))||0;
      if(pk==='attackbonus')cur.atkB=pv; else if(pk==='strengthbonus')cur.strB=pv; else if(pk==='stabdefence')cur.stabD=pv; else if(pk==='slashdefence')cur.slashD=pv; else if(pk==='crushdefence')cur.crushD=pv; }
  }
  flush();
}

// spawns
const packContent = readFileSync(join(CONTENT,'pack','npc.pack'),'utf-8');
