for (const line of packContent.split('\n')) { const eq=line.indexOf('='); if(eq===-1)continue; const id=parseInt(line.slice(0,eq)); const nm=line.slice(eq+1).trim(); if(!isNaN(id)&&nm)idToName.set(id,nm); }
const mapsDir = join(CONTENT,'maps');
const nearest = new Map<string, number>(); // key -> min dist
const px=3222,pz=3222;
for (const file of readdirSync(mapsDir).filter(f=>f.endsWith('.jm2'))) {
  const m=file.match(/^m(\d+)_(\d+)\.jm2$/); if(!m)continue; const mx=parseInt(m[1]),mz=parseInt(m[2]);
  const content=readFileSync(join(mapsDir,file),'utf-8'); const idx=content.indexOf('==== NPC ===='); if(idx===-1)continue;
  const after=content.slice(idx+13); const nx=after.indexOf('===='); const block=nx===-1?after:after.slice(0,nx);
  for (const line of block.split('\n')) { const t=line.trim(); const mm=t.match(/^(\d+)\s+(\d+)\s+(\d+):\s*(\d+)$/); if(!mm)continue;
    const lx=parseInt(mm[2]),lz=parseInt(mm[3]),id=parseInt(mm[4]); const nm=idToName.get(id); if(!nm)continue;
    const gx=mx*64+lx,gz=mz*64+lz; const dist=Math.hypot(gx-px,gz-pz);
    const cur=nearest.get(nm); if(cur===undefined||dist<cur)nearest.set(nm,dist);
  }
}

// our stats: attack 40, bronze sword attack bonus ~ +7, strength 40, str bonus +7
const A = 40 + 7 + 8; // attack level + attack bonus + 8
function hc(defLv:number, defB:number){ const d=defLv+defB+8; return A>d ? 1-(d+2)/(2*(A+1)) : A/(2*(d+1)); }
const ourStr = 40 + 7; // str level + str bonus
const ourMax = Math.floor((ourStr*64+320)/640);

const rows: any[] = [];
for (const n of byKey.values()) {
  if (n.vislevel < 20) continue;
  const dist = nearest.get(n.key);
  const stabD = n.stabD || 0;
  const h = hc(n.defence, stabD);
  const d = h * (ourMax/2) / 2.4;
  const val = n.vislevel * d/(1+d);
  // incoming: npc attack + atkB vs our def 1 + shield ~4 +8
  const od = 1+4+8; const oa = n.attack + (n.atkB||0) + 8;
  const inHc = oa>od ? 1-(od+2)/(2*(oa+1)) : oa/(2*(od+1));
  const npcMax = Math.floor((n.strength*(n.strB+64)+320)/640);
  const inDps = inHc * (npcMax/2) / 2.4;
  rows.push({ ...n, dist, val, d, h, ourMax, npcMax, inDps });
}
