  pos:[st.player.worldX,st.player.worldZ], hp:st.player.hp, cb:st.player.combatLevel,
  chat:sdk.getChat({limit:15})};

await bot.equipItem(/^bronze sword$/i); await bot.equipItem(/^wooden shield$/i);
await bot.walkTo(2909,3294,8,{timeout:60000});
const startXp={}; for(const s of sdk.getSkills()) startXp[s.name]=s.experience;
const end=Date.now()+150000;
let attacks=0, retreats=0;
while(Date.now()<end){
  const st=sdk.getState();
  if(!st||!st.player){await sdk.waitForTicks(1);continue;}
  if(st.player.isDead){ await sdk.waitForTicks(15); continue; }
  if(st.dialog?.isOpen){await bot.dismissBlockingUI();}
  if(st.player.hp<=16){ retreats++; try{await bot.walkTo(2920,3278,4,{timeout:6000});}catch(e){} await sdk.waitForTicks(15); continue; }
  if(st.player.combat.inCombat){ await sdk.waitForTicks(2); continue; }
  const hob=st.nearbyNpcs.filter(n=>/^hobgoblin$/i.test(n.name)).sort((a,b)=>(b.combatLevel-a.combatLevel)||(a.distance-b.distance))[0];
  if(hob){ try{ await bot.attack(hob); attacks++; }catch(e){} } else { await sdk.waitForTicks(2); }
}
const xp={}; for(const s of sdk.getSkills()){if(s.experience!==startXp[s.name])xp[s.name]=s.experience-startXp[s.name];}
const st=sdk.getState();
return {attacks, retreats, xp, hp:st.player.hp, cb:st.player.combatLevel, pos:[st.player.worldX,st.player.worldZ], minLeft:((Date.parse('2026-10-19T19:31:51.938Z')-Date.now())/60000).toFixed(2)};
